export interface CdpEvent { readonly method: string; readonly params: Record<string, unknown>; readonly sessionId?: string }
export class CdpError extends Error { readonly method: string; readonly code: number }
export class CdpClosedError extends Error {}
export interface CdpConnection {
  send(method: string, params?: Record<string, unknown>, sessionId?: string): Promise<Record<string, unknown>>;
  onEvent(listener: (event: CdpEvent) => void): () => void;
  waitForEvent(method: string, options: { readonly sessionId?: string; readonly timeoutMs: number; readonly predicate?: (event: CdpEvent) => boolean }): Promise<CdpEvent>;
  readonly closed: Promise<void>; // resolves on transport close; every pending send rejects with CdpClosedError
  dispose(): void;
}
export function connectPipe(toChrome: NodeJS.WritableStream, fromChrome: NodeJS.ReadableStream): CdpConnection;
Rules: frames are JSON + '\0', accumulated as Buffers (never string concatenation, so split UTF-8 survives); 'error' listeners on both streams and on the child (EPIPE closes the connection instead of crashing the MCP process, measured hazard); no Node 22-only APIs (no Promise.withResolvers, no global WebSocket).
